import { topbar } from '../../front_office/styles/frontOfficeClasses';

export const topbarClasses = topbar;

export default function ClinicDoctorTopbar({ doctorLabel, initials, live }) {
  return (
    <header className={topbar.root}>
      <div>
        <p className={topbar.brand}>Master Doctor</p>
        <p className="text-xs text-slate-500">
          Consultation queue
          {' · '}
          <span className="inline-flex items-center gap-1">
            <span
              className={`inline-block h-2 w-2 rounded-full ${live ? 'bg-emerald-500' : 'bg-slate-300'}`}
              aria-hidden
            />
            {live ? 'Live' : 'Offline'}
          </span>
        </p>
      </div>
      <div className="flex items-center gap-3">
        <span className="hidden text-sm font-medium text-slate-700 sm:inline">{doctorLabel}</span>
        <span
          className="flex h-9 w-9 items-center justify-center rounded-full bg-teal-600 text-sm font-bold text-white"
          aria-hidden
        >
          {initials}
        </span>
      </div>
    </header>
  );
}
